import{_ as a,o as t,c as s,a6 as i}from"./chunks/framework.CKIbuWFA.js";const u=JSON.parse('{"title":"Event normalization, batches and gaps","description":"","frontmatter":{"title":"Event normalization, batches and gaps","docId":"developer.events","translationKey":"developer.events","locale":"en","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"caded5529a62e826a91d2deb86936c29c709ac713c2a0cd021f467b1dfa2b6e7","translationRevision":"caded5529a62e826a91d2deb86936c29c709ac713c2a0cd021f467b1dfa2b6e7","order":100},"headers":[],"relativePath":"en/developer/events.md","filePath":"en/developer/events.md","lastUpdated":1794611623000}'),n={name:"en/developer/events.md"};function o(r,e,l,d,c,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="event-normalization-batches-and-gaps" tabindex="-1">Event normalization, batches and gaps <a class="header-anchor" href="#event-normalization-batches-and-gaps" aria-label="Permalink to &quot;Event normalization, batches and gaps {#event-normalization-batches-and-gaps}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Goal and prerequisites {#goal-and-prerequisites}&quot;">​</a></h2><p>Consume LIVE events without double counting or mistaking presentation recovery for execution. Understand <a href="./storage.html">persistence</a> and use sanitized fixtures rather than real account captures. <code>tiktools-tiktok</code> wraps the pinned signer/decoder dependencies and exports stable TikTools values; core does not expose protobuf objects as an application API.</p><h2 id="follow-the-implemented-pipeline" tabindex="-1">Follow the implemented pipeline <a class="header-anchor" href="#follow-the-implemented-pipeline" aria-label="Permalink to &quot;Follow the implemented pipeline {#follow-the-implemented-pipeline}&quot;">​</a></h2><p>Ingress captures the original creator/room connection context before asynchronous work. Normalization produces chat, gift, like, social and lifecycle values. Core publishes originals and manages accounting/effect work separately. Processors may attach bounded derived evidence under <code>event.intel</code>; failures preserve raw events with degraded diagnostics. Generated automation contracts describe only emitted fields.</p><p>Backend replay identity includes creator, room, method, type and a nonzero message ID. Missing IDs cannot establish replay. Gift combo accounting uses sender/gift/group identity and cumulative maxima, so a final packet cannot award the same quantity twice. Unknown prices remain zero. Aggregate transitions can support a threshold crossing using <code>previous &lt; threshold &lt;= total</code>; they do not replace public originals.</p><h2 id="implement-a-consumer" tabindex="-1">Implement a consumer <a class="header-anchor" href="#implement-a-consumer" aria-label="Permalink to &quot;Implement a consumer {#implement-a-consumer}&quot;">​</a></h2><ol><li>Use types from <code>src/automation/contracts/generated/</code> or the widget domain envelope parser for that boundary.</li><li>Preserve delivery cursors through serialization and deduplicate overlap when joining realtime and backfill.</li><li>Process ordered batches without issuing one reactive render per event.</li><li>Surface explicit gap/overload signals. Recover presentation with bounded pages or a fresh snapshot, never by invoking points or actions again.</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> contracts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> live-feed-state</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> automation</span></span></code></pre></div><p>The <a href="https://github.com/nglmercer/TikTools-app/tree/remake/crates/tiktools-core/src/contracts" target="_blank" rel="noreferrer">Rust contract source</a> generates the event registry, schemas and samples; do not reproduce complete event-field tables by hand.</p><h2 id="expected-result-and-status" tabindex="-1">Expected result and status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Expected result and status {#expected-result-and-status}&quot;">​</a></h2><p>Reconnect overlap is deduplicated only while the identified event remains in the current finite replay store. Queues, counters, history and replay caches remain bounded. This is not an unlimited event archive or a universal exactly-once guarantee. Capacity exhaustion and unavailable persistence have explicit health consequences.</p><h2 id="recover-and-verify" tabindex="-1">Recover and verify <a class="header-anchor" href="#recover-and-verify" aria-label="Permalink to &quot;Recover and verify {#recover-and-verify}&quot;">​</a></h2><p>Use sanitized gift/emote fixtures and test final-combo packets, missing IDs, cross-room identity and reconnect gaps. Inspect the current <code>Cargo.toml</code> signer revision rather than copying a hash from an old reliability report. Unknown upstream methods stay unknown until normalization and generated contracts deliberately add them.</p><h2 id="operational-details" tabindex="-1">Operational details <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Operational details {#operational-details}&quot;">​</a></h2><p>Current defaults (2026-11-13) are limits of this implementation, not an SLA. LIVE ingress holds 2,048 items and the effects lane 128; these are item counts, not byte budgets. Lifecycle events wait for capacity. Gifts/follows/shares wait at most one second before a gap-reported drop. Chat/likes/joins/other data drop immediately when saturated. Inspect ingress counters including <code>droppedCritical</code>, dropped like batches/units and effects losses; a dropped input can mean its effects never ran. Backfill repairs presentation only, never points or actions.</p><p>Deduplication holds at most 4,096 identified events for 300 seconds in process memory, surviving reconnects only while that store lives. TTL expiry, capacity eviction, missing IDs or restart remove that protection. Reconnection overlap is protected only within these bounds.</p><p><code>ui.feed.backfill</code> takes <code>{version:1,after:0,limit:64}</code> with global numeric cursors and limits 1–512; inspect <code>oldestCursor</code>, <code>latestCursor</code>, <code>gap</code> and <code>truncated</code>, continuing from the last received event cursor. <code>ui.feed.creator</code> uses <code>{creatorId,streamId,after,limit}</code> with string cursors, a creator-specific stream, limits 1–64 and a byte budget. Do not interchange cursor types. On changed/evicted streams, future cursors, ingress gaps or <code>CreatorFeedUnavailable</code>, refresh authoritative presentation and explicitly mark missing history; never synthesize effects.</p><p>TikTok initialization performs session, room, gift catalog, signing-bundle and socket stages. Bundle configuration: <code>TIKTOOLS_TIKTOK_SIGNING_BUNDLE</code>, <code>TIKTOOLS_TIKTOK_BUNDLE_CACHE</code>, <code>TIKTOOLS_TIKTOK_BUNDLE_URL</code>. Defaults allow five attempts, initial 2 s backoff capped at 30 s. HTTP 429 uses Retry-After or an increasing 30–300 s minimum plus jitter, at most two rate-limit retries, with cooldown retained after cancellation/exhaustion. Other retries require transient transport failures. Inspect <code>Reconnecting { attempt, delay_ms }</code> and the failing stage; never attach cookies or private signing material to reports.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system.health</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div>`,20)])])}const m=a(n,[["render",o]]);export{u as __pageData,m as default};
